fn binary_search(v: &Vec<u64>, k: u64) -> usize {
    // We maintain the invariant that k is somewhere in v[low..=high].
    let mut low = 0;
    let mut high = v.len() - 1;

    // Narrow the interval until low == high.
    while low < high {
        let mid = low + (high - low) / 2;
        if v[mid] < k {
            // k must be to the right of mid
            low = mid + 1;
        } else {
            // v[mid] >= k, so k is in [low..=mid]
            high = mid;
        }
    }

    // When low == high, that index must contain k
    low
}

